import * as T from 'three';
import {mergeGeometries} from './vendor/BufferGeometryUtils.js';
import {BUS_SPEC,buildLoftedBusBodyGeometry,buildBusSignGeometry,buildBusWheelGeo} from './vendor/slop/bus-model.js';
import {carNight} from './slop-webgl.js?v=2';
export const BUS_COUNT=4;
export const BUS_SOURCE='https://github.com/mrdoob/slop-newyork';
export function busRoadFeatures(features){return features.filter(f=>f.kind==='road'&&f.width>=(['yes','1','-1'].includes(f.tags?.oneway)?9:12)&&['primary','secondary','tertiary','trunk'].includes(f.tags?.highway)&&(!f.tags?.bridge||f.tags.bridge==='no')&&(!f.tags?.tunnel||f.tags.tunnel==='no')&&Number(f.tags?.layer||0)===0);}
export function busContinuations(lane){const p=lane.pts.at(-1),prev=lane.pts.at(-2),dx=p[0]-prev[0],dz=p[1]-prev[1];return lane.next.filter(n=>{const a=n.pts[0],b=n.pts[1],angle=Math.atan2(dx*(b[1]-a[1])-dz*(b[0]-a[0]),dx*(b[0]-a[0])+dz*(b[1]-a[1]));return Math.abs(angle)<.35&&Math.hypot(p[0]-a[0],p[1]-a[1])<1.2;});}
export function busFootprint(v){const fx=-Math.sin(v.heading),fz=-Math.cos(v.heading);return [-5.2,-3.9,-2.6,-1.3,0,1.3,2.6,3.9,5.2].map(o=>[v.x+fx*o,v.z+fz*o,1.5,(v.pull??0)>.6]);}
export function buildBusGeometry(){const parts=[buildLoftedBusBodyGeometry()];for(const side of [-1,1])for(const z of [-BUS_SPEC.wheelZ,BUS_SPEC.wheelZ]){const g=buildBusWheelGeo(side),a=g.attributes.partId;for(let i=0;i<a.count;i++)a.setX(i,a.getX(i)===2?3:4);g.translate(side*BUS_SPEC.wheelX,BUS_SPEC.wheelRadius,z);parts.push(g);}const g=mergeGeometries(parts);parts.forEach(p=>p.dispose());g.computeBoundingBox();g.computeBoundingSphere();return g;}
function rolling(sh){sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nattribute float partId;attribute float wheelRoll;');sh.vertexShader=sh.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nif(partId>2.5){float c=cos(wheelRoll),s=sin(wheelRoll),z0=position.z>0.?3.6:-3.6;vec2 q=transformed.yz-vec2(.48,z0);transformed.yz=vec2(c*q.x-s*q.y,s*q.x+c*q.y)+vec2(.48,z0);}');sh.vertexShader=sh.vertexShader.replace('#include <beginnormal_vertex>','#include <beginnormal_vertex>\nif(partId>2.5){float c=cos(wheelRoll),s=sin(wheelRoll);objectNormal.yz=vec2(c*objectNormal.y-s*objectNormal.z,s*objectNormal.y+c*objectNormal.z);}');}
export function createBusDepth(){const m=new T.MeshDepthMaterial({depthPacking:T.RGBADepthPacking});m.onBeforeCompile=rolling;m.customProgramCacheKey=()=>'slop-bus-depth-v1';return m;}
export function createBusMaterial(){const m=new T.MeshStandardMaterial({roughness:.45,metalness:.18});m.onBeforeCompile=sh=>{sh.uniforms.uNight=carNight;rolling(sh);sh.vertexShader=sh.vertexShader.replace('#include <common>','#include <common>\nattribute vec4 carState;varying vec3 vBP;varying vec3 vBN;varying float vPart;varying float vBrake;').replace('#include <begin_vertex>','#include <begin_vertex>\nvBP=position;vBN=normal;vPart=partId;vBrake=carState.x;');sh.fragmentShader=sh.fragmentShader.replace('#include <common>','#include <common>\nuniform float uNight;varying vec3 vBP;varying vec3 vBN;varying float vPart;varying float vBrake;\nfloat busRect(vec2 p,vec2 h,float r){vec2 q=abs(p)-h+r;float d=length(max(q,vec2(0.)))+min(max(q.x,q.y),0.)-r;float w=max(fwidth(d),.002);return 1.-smoothstep(-w,w,d);}')
.replace('#include <color_fragment>','#include <color_fragment>\n'+[
'vec3 p=vBP,n=normalize(vBN);float body=1.-step(.5,vPart),trim=step(.5,vPart)*(1.-step(1.5,vPart)),pod=step(1.5,vPart)*(1.-step(2.5,vPart)),tyre=step(2.5,vPart)*(1.-step(3.5,vPart)),alloy=step(3.5,vPart);',
'float front=smoothstep(.1,.35,n.z)*step(4.88,p.z)*body,rear=smoothstep(.1,.35,-n.z)*step(p.z,-4.88)*body,side=smoothstep(.5,.75,abs(n.x))*body,curb=1.-step(0.,p.x);',
'float band=busRect(vec2(p.z+.5,p.y-1.84),vec2(4.82,.60),.08)*side,mullion=smoothstep(.03,.045,abs((fract(p.z*.8+.35)-.5)*1.25));',
'float fg=busRect(vec2(p.x,p.y-1.82),vec2(1.2,.58),.14)*smoothstep(.012,.024,abs(p.x))*front,rg=busRect(vec2(p.x,p.y-2.06),vec2(.92,.36),.08)*rear;',
'float d0=busRect(vec2(p.z-4.86,p.y-1.44),vec2(.5,1.),.05)*side*curb,d1=busRect(vec2(p.z+1.01,p.y-1.44),vec2(.51,1.),.05)*side*curb;',
'float doorGlass=max(busRect(vec2(abs(p.z-4.86)-.25,p.y-1.50),vec2(.20,.84),.035)*d0,busRect(vec2(abs(p.z+1.01)-.255,p.y-1.50),vec2(.204,.84),.035)*d1);',
'float driverWin=busRect(vec2(p.z-4.86,p.y-1.88),vec2(.5,.64),.1)*side*(1.-curb);float glass=clamp(max(max(fg,rg),max(max(band*mullion,doorGlass),driverWin)),0.,1.);float stripe=smoothstep(.90,.93,p.y)*(1.-smoothstep(1.17,1.20,p.y));vec3 col=mix(vec3(.86,.91,.95),vec3(.018,.18,.47),stripe);col=mix(col,vec3(.015,.025,.04),max(d0,d1));col=mix(col,mix(vec3(.018,.035,.060),vec3(.06,.10,.15),clamp(p.y-1.3,0.,1.)),glass);',
'float vent=busRect(vec2(p.x,p.y-.98),vec2(.78,.34),.05)*rear;col=mix(col,vec3(.04,.05,.06)*(.4+.45*step(.5,fract(p.y*16.))),vent);',
'float head=busRect(vec2(abs(p.x)-.82,p.y-.80),vec2(.23,.065),.04)*front,tail=busRect(vec2(abs(p.x)-1.04,p.y-1.05),vec2(.075,.14),.04)*rear;',
'col=mix(col,vec3(.82,.91,1.),head);col=mix(col,vec3(.45,.012,.018),tail);float plate=busRect(vec2(p.x,p.y-.77),vec2(.16,.06),.008)*max(front,rear);col=mix(col,vec3(.9,.91,.86),plate);',
'col=mix(col,vec3(.025,.032,.04),trim);col=mix(col,vec3(.60,.65,.70),pod);col=mix(col,vec3(.012,.016,.02),tyre);col=mix(col,vec3(.43,.49,.55),alloy);diffuseColor.rgb=col;'
].join('\n')).replace('#include <roughnessmap_fragment>','#include <roughnessmap_fragment>\nroughnessFactor=mix(.48,.18,glass);roughnessFactor=mix(roughnessFactor,.86,max(trim,tyre));').replace('#include <metalnessmap_fragment>','#include <metalnessmap_fragment>\nmetalnessFactor=mix(.18,.7,alloy);').replace('#include <emissivemap_fragment>','#include <emissivemap_fragment>\ntotalEmissiveRadiance=vec3(.78,.88,1.)*head*uNight*1.5+vec3(1.,.012,.02)*tail*(.25+uNight*.5+vBrake*1.5);');};m.customProgramCacheKey=()=>'slop-bus-webgl-v1';return m;}
export function createBusSignMaterial(){const c=document.createElement('canvas');c.width=1024;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle='#080b0d';ctx.fillRect(0,0,1024,128);ctx.fillStyle='#ffcf70';ctx.font='bold 78px "Microsoft JhengHei",sans-serif';ctx.textBaseline='middle';ctx.textAlign='center';ctx.fillText('示意公車　信義街景',512,64,970);const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;return new T.MeshBasicMaterial({map:tex});}
export function makeBusKit(){return {bus:true,length:12.1,radius:1.5,wheelRadius:.48,body:buildBusGeometry(),sign:buildBusSignGeometry()};}
